#!/usr/bin/env node
// Generated by scripts/build.mjs from src/core.js, src/sessions.js, src/stats.js, src/doctor.js, src/cli.js. Do not edit.
import { existsSync, mkdirSync, readFileSync, readdirSync, realpathSync, statSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { basename, dirname, join, resolve as resolvePath, sep } from 'node:path';
import { spawn } from 'node:child_process';
import { createServer } from 'node:http';
import { fileURLToPath } from 'node:url';
// Superwiki core: vault model, derived task state and lint. Pure: no fs, no DOM.
// Runs in Node (docs/.sw/sw.mjs) and inlined in the viewer, so both report the same findings.

export const STATUSES = ['todo', 'in-progress', 'done', 'cancelled'];
export const VAULT_FOLDERS = ['wiki', 'tasks', 'plans'];
const ROOT_PAGES = ['index', 'log'];

// ---------- Frontmatter (the YAML subset Superwiki writes: scalars, [inline, lists], "- block" lists) ----------
function scalar(s) {
  let v = String(s).trim();
  if (v.length > 1 && v.startsWith('"') && v.endsWith('"')) v = v.slice(1, -1).replace(/\\(["\\])/g, '$1');
  else if (v.length > 1 && v.startsWith("'") && v.endsWith("'")) v = v.slice(1, -1).replace(/''/g, "'");
  if (v.startsWith('[[') && v.endsWith(']]')) v = v.slice(2, -2).trim();
  return v;
}

function stripComment(line) {
  return /["']/.test(line) ? line : line.replace(/(^|\s)#.*$/, '');
}

export function parseFrontmatter(text) {
  const src = String(text ?? '').replace(/^﻿/, '');
  const m = /^---[ \t]*\r?\n([\s\S]*?)\r?\n---[ \t]*(?:\r?\n|$)/.exec(src);
  if (!m) return { data: null, body: src, bodyLine: 1 };
  const data = {};
  let key = null;
  for (const raw of m[1].split(/\r?\n/)) {
    const line = stripComment(raw);
    if (!line.trim()) continue;
    const item = /^\s*-\s+(.*)$/.exec(line);
    if (item && key) {
      if (!Array.isArray(data[key])) data[key] = [];
      data[key].push(scalar(item[1]));
      continue;
    }
    const kv = /^([A-Za-z_][\w-]*):\s*(.*)$/.exec(line);
    if (!kv) continue;
    key = kv[1];
    const v = kv[2].trim();
    if (v === '') data[key] = null;
    else if (v.startsWith('[') && v.endsWith(']') && !v.startsWith('[[')) {
      data[key] = v.slice(1, -1).split(',').map(scalar).filter(Boolean);
    } else data[key] = scalar(v);
  }
  return { data, body: src.slice(m[0].length), bodyLine: m[0].split('\n').length };
}

export function asList(v) {
  if (v == null || v === '') return [];
  return Array.isArray(v) ? v : [v];
}

// ---------- Wikilinks ----------
const WIKILINK = /(!?)\[\[([^\[\]|#]+)(#[^\[\]|]*)?(?:\|([^\[\]]*))?\]\]/g;
const isAttachment = target => /\.[A-Za-z0-9]{2,5}$/.test(target) && !/\.md$/i.test(target);

// Links in a markdown body. Fenced and inline code is skipped; `line` is 1-based within the body.
export function extractWikilinks(body) {
  const out = [];
  let fenced = false;
  String(body ?? '').split(/\r?\n/).forEach((raw, i) => {
    if (/^\s*(```|~~~)/.test(raw)) { fenced = !fenced; return; }
    if (fenced) return;
    const line = raw.replace(/`[^`]*`/g, '');
    for (const m of line.matchAll(WIKILINK)) {
      const target = m[2].trim().replace(/\.md$/i, '');
      if (m[1] === '!' || isAttachment(m[2].trim())) continue;
      out.push({ target, heading: m[3] ? m[3].slice(1) : null, alias: m[4] ?? null, line: i + 1 });
    }
  });
  return out;
}

// ---------- Vault ----------
const key = name => String(name).toLowerCase();
const areaOf = id => (String(id).includes('-') ? String(id).slice(0, String(id).lastIndexOf('-')) : '');

// files: [{ path, text }] with paths relative to docs/ ("wiki/foo.md"). Anything outside
// index.md, log.md, wiki/, tasks/ and plans/ belongs to other tools and is ignored.
export function buildVault(files) {
  const pages = [];
  const names = new Map();
  for (const f of files) {
    const path = String(f.path).replace(/\\/g, '/').replace(/^\.?\//, '');
    if (!/\.md$/i.test(path)) continue;
    const parts = path.split('/');
    const name = parts[parts.length - 1].replace(/\.md$/i, '');
    let folder;
    if (parts.length === 1) { if (!ROOT_PAGES.includes(name)) continue; folder = 'root'; }
    else if (VAULT_FOLDERS.includes(parts[0])) folder = parts[0];
    else continue;
    const fm = parseFrontmatter(f.text);
    const page = { path, folder, name, nested: parts.length > 2, data: fm.data || {}, hasFrontmatter: !!fm.data, body: fm.body, bodyLine: fm.bodyLine, links: extractWikilinks(fm.body), inbound: [] };
    pages.push(page);
    if (!names.has(key(name))) names.set(key(name), []);
    names.get(key(name)).push(page);
  }
  pages.sort((a, b) => a.path.localeCompare(b.path));
  const vault = { pages, names, tasks: new Map(), plans: new Map(), index: null, log: null };
  vault.index = pages.find(p => p.folder === 'root' && p.name === 'index') || null;
  vault.log = pages.find(p => p.folder === 'root' && p.name === 'log') || null;
  for (const p of pages) for (const l of p.links) {
    const t = resolve(vault, l.target);
    if (t && t !== p && !t.inbound.includes(p)) t.inbound.push(p);
  }
  for (const p of pages) {
    if (p.folder === 'plans') vault.plans.set(key(p.name.replace(/-plan$/i, '')), p);
    if (p.folder !== 'tasks') continue;
    const d = p.data;
    const id = String(d.id || p.name);
    vault.tasks.set(key(id), {
      id, page: p, area: areaOf(id), title: d.title || '', status: d.status || '',
      deps: asList(d.deps).map(String), softDeps: asList(d.soft_deps).map(String),
      milestone: d.milestone || '', priority: d.priority == null || d.priority === '' ? null : Number(d.priority),
      started: d.started || '', finished: d.finished || '',
      // Any value asks for a separate review before the task may be done; the value names the kind.
      review: d.review ? String(d.review) : '',
      state: null, wave: 0, dependents: [], plan: null,
    });
  }
  derive(vault);
  return vault;
}

export function resolve(vault, target) {
  const hit = vault.names.get(key(String(target).split('/').pop().replace(/\.md$/i, '')));
  return hit ? hit[0] : null;
}

export const taskOf = (vault, id) => vault.tasks.get(key(id)) || null;

// state: done | cancelled | progress | ready | blocked. wave: longest hard-dependency chain below the task.
function derive(vault) {
  const depth = new Map();
  const waveOf = (t, trail) => {
    if (depth.has(t)) return depth.get(t);
    if (trail.has(t)) return 0;
    trail.add(t);
    let w = 0;
    for (const id of t.deps) { const d = taskOf(vault, id); if (d) w = Math.max(w, waveOf(d, trail) + 1); }
    trail.delete(t);
    depth.set(t, w);
    return w;
  };
  for (const t of vault.tasks.values()) {
    t.plan = vault.plans.get(key(t.id)) || null;
    t.wave = waveOf(t, new Set());
    const open = t.deps.filter(id => taskOf(vault, id)?.status !== 'done');
    t.openDeps = open;
    t.openSoftDeps = t.softDeps.filter(id => taskOf(vault, id)?.status !== 'done');
    t.state = t.status === 'done' ? 'done' : t.status === 'cancelled' ? 'cancelled' : t.status === 'in-progress' ? 'progress' : open.length ? 'blocked' : 'ready';
    for (const id of [...t.deps, ...t.softDeps]) {
      const d = taskOf(vault, id);
      if (d && !d.dependents.includes(t.id)) d.dependents.push(t.id);
    }
  }
}

function cycles(vault) {
  const found = [];
  const seen = new Set();
  const state = new Map();
  const visit = (t, trail) => {
    state.set(t, 1);
    trail.push(t.id);
    for (const id of [...t.deps, ...t.softDeps]) {
      const d = taskOf(vault, id);
      if (!d) continue;
      if (state.get(d) === 1) {
        const loop = trail.slice(trail.indexOf(d.id));
        const sig = [...loop].sort().join(',');
        if (!seen.has(sig)) { seen.add(sig); found.push([...loop, d.id]); }
      } else if (!state.get(d)) visit(d, trail);
    }
    trail.pop();
    state.set(t, 2);
  };
  for (const t of vault.tasks.values()) if (!state.get(t)) visit(t, []);
  return found;
}

// ---------- Lint ----------
// Finding: { level: 'error' | 'warn', code, path, message }.
export function lint(vault) {
  const out = [];
  const add = (level, code, path, message) => out.push({ level, code, path, message });

  for (const [, list] of vault.names) {
    if (list.length > 1) add('error', 'duplicate-name', list[0].path, `file name is not unique: ${list.map(p => p.path).join(', ')}`);
  }
  if (!vault.index) add('error', 'missing-index', 'index.md', 'docs/index.md is missing');

  for (const p of vault.pages) {
    if (p.nested) add('warn', 'nested-page', p.path, `${p.folder}/ is flat; move the file up`);
    // The log is history: entries keep the names pages had when they were written.
    if (p !== vault.log) for (const l of p.links) {
      if (!resolve(vault, l.target)) add('error', 'broken-link', p.path, `line ${p.bodyLine + l.line - 1}: [[${l.target}]] has no target`);
    }
    if (p.folder === 'wiki') {
      if (!p.data.type) add('error', 'missing-field', p.path, 'frontmatter `type` is missing');
      if (!p.data.summary) add('warn', 'missing-field', p.path, 'frontmatter `summary` is missing');
      if (vault.index && !vault.index.links.some(l => resolve(vault, l.target) === p)) add('warn', 'not-in-index', p.path, 'page is not listed in index.md');
      // A source summary is reachable from the index and need not be cited yet; an area guide is found by its area, not by links.
      if (p.data.type !== 'source' && p.data.type !== 'guide' && !p.inbound.some(q => q !== vault.index && q !== vault.log)) add('warn', 'orphan-page', p.path, 'no page links here');
    }
    if (p.folder === 'plans') {
      const id = /-plan$/i.test(p.name) ? p.name.replace(/-plan$/i, '') : null;
      if (!id) add('error', 'plan-name', p.path, 'plan files are named <ID>-plan.md');
      else if (!taskOf(vault, id)) add('error', 'orphan-plan', p.path, `no task ${id} for this plan`);
      else if (p.data.task && key(p.data.task) !== key(id)) add('error', 'plan-task-mismatch', p.path, `frontmatter task ${p.data.task} does not match file name`);
      if (p.data.type !== 'plan') add('warn', 'missing-field', p.path, 'frontmatter `type: plan` is missing');
    }
  }

  for (const t of vault.tasks.values()) {
    const path = t.page.path;
    if (t.page.data.type !== 'task') add('warn', 'missing-field', path, 'frontmatter `type: task` is missing');
    if (!t.page.data.id) add('error', 'missing-field', path, 'frontmatter `id` is missing');
    else if (key(t.id) !== key(t.page.name)) add('error', 'id-mismatch', path, `id ${t.id} does not match file name`);
    if (!/^[A-Za-z][A-Za-z0-9]*-\d+$/.test(t.id)) add('error', 'bad-id', path, `id ${t.id} is not <AREA>-<number>`);
    if (!t.title) add('error', 'missing-field', path, 'frontmatter `title` is missing');
    if (!STATUSES.includes(t.status)) add('error', 'bad-status', path, `status "${t.status}" is not one of ${STATUSES.join(', ')}`);
    for (const id of [...t.deps, ...t.softDeps]) {
      const d = taskOf(vault, id);
      if (!d) add('error', 'unknown-dep', path, `depends on ${id}, which does not exist`);
      else if (d.status === 'cancelled' && t.status !== 'cancelled' && t.status !== 'done') add('warn', 'cancelled-dep', path, `depends on cancelled task ${id}`);
    }
    const hardOpen = t.openDeps.filter(id => taskOf(vault, id));
    const softOpen = t.openSoftDeps.filter(id => taskOf(vault, id));
    if (t.status === 'in-progress' && hardOpen.length) add('error', 'started-before-deps', path, `in-progress but not done: ${hardOpen.join(', ')}`);
    if (t.status === 'done' && (hardOpen.length || softOpen.length)) add('error', 'done-before-deps', path, `done but not done: ${[...hardOpen, ...softOpen].join(', ')}`);
    if ((t.status === 'in-progress' || t.status === 'done') && !t.started) add('warn', 'missing-date', path, '`started` is empty');
    if (t.status === 'done' && !t.finished) add('warn', 'missing-date', path, '`finished` is empty');
  }
  for (const loop of cycles(vault)) add('error', 'dep-cycle', taskOf(vault, loop[0]).page.path, `dependency cycle: ${loop.join(' -> ')}`);

  const rank = { error: 0, warn: 1 };
  return out.sort((a, b) => rank[a.level] - rank[b.level] || a.path.localeCompare(b.path) || a.code.localeCompare(b.code));
}

// ---------- Queries ----------
const STATES = ['ready', 'progress', 'blocked', 'done', 'cancelled'];
const idOrder = (a, b) => a.area.localeCompare(b.area) || Number(a.id.split('-').pop()) - Number(b.id.split('-').pop());
// Runnable order: fewest unfinished layers first, then explicit priority, then id.
export const taskOrder = (a, b) => a.wave - b.wave || (a.priority ?? Infinity) - (b.priority ?? Infinity) || idOrder(a, b);

export function summary(vault) {
  const zero = () => Object.fromEntries([['total', 0], ...STATES.map(s => [s, 0])]);
  const areas = new Map();
  const total = zero();
  for (const t of [...vault.tasks.values()].sort(idOrder)) {
    if (!areas.has(t.area)) areas.set(t.area, zero());
    for (const c of [areas.get(t.area), total]) { c.total++; c[t.state]++; }
  }
  return { areas, total, wikiPages: vault.pages.filter(p => p.folder === 'wiki').length };
}

export function tasksIn(vault, state) {
  return [...vault.tasks.values()].filter(t => t.state === state).sort(taskOrder);
}

// Numbers are never reused: cancelled tasks stay on disk and keep theirs.
export function nextId(vault, area) {
  let max = 0;
  let width = 2;
  for (const t of vault.tasks.values()) {
    if (key(t.area) !== key(area)) continue;
    const n = t.id.split('-').pop();
    if (/^\d+$/.test(n)) { max = Math.max(max, Number(n)); width = Math.max(width, n.length); }
  }
  return `${area}-${String(max + 1).padStart(width, '0')}`;
}

// Hard dependents that become ready the moment this task is done.
export function unblockedBy(vault, id) {
  const t = taskOf(vault, id);
  if (!t) return [];
  return t.dependents.map(d => taskOf(vault, d))
    .filter(d => d && d.status === 'todo' && d.deps.includes(t.id) && d.openDeps.every(o => o === t.id))
    .map(d => d.id);
}

// Keyword search over the vault. Pages matching more distinct terms come first; then lessons; a hit
// in the name, title or summary outweighs hits in the body. Returns [{ page, score, line }].
export function search(vault, query, limit = 8) {
  const terms = [...new Set(String(query).toLowerCase().split(/[^\p{L}\p{N}_-]+/u).filter(w => w.length > 1))];
  if (!terms.length) return [];
  // A term matches at the start of a word, so "sync" finds "syncing" but "hang" does not find "change".
  const res = terms.map(t => new RegExp(`(?<![\\p{L}\\p{N}])${t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`, 'u'));
  const out = [];
  for (const p of vault.pages) {
    if (p === vault.index || p === vault.log) continue;
    const head = `${p.name} ${p.data.title || ''} ${p.data.summary || ''}`.toLowerCase();
    const body = p.body.toLowerCase();
    let matched = 0;
    let score = 0;
    for (const re of res) {
      const inHead = re.test(head);
      const hits = Math.min((body.match(new RegExp(re.source, 'gu')) || []).length, 5);
      if (inHead || hits) matched++;
      score += (inHead ? 5 : 0) + hits;
    }
    if (!matched) continue;
    const line = p.body.split(/\r?\n/).find(l => res.some(re => re.test(l.toLowerCase()))) || '';
    out.push({ page: p, matched, score, line: line.trim().slice(0, 140) });
  }
  // Among pages matching the same number of terms, a recorded lesson is the most useful thing to read first.
  const lesson = h => (h.page.data.type === 'lesson' ? 1 : 0);
  return out.sort((a, b) => b.matched - a.matched || lesson(b) - lesson(a) || b.score - a.score || a.page.path.localeCompare(b.page.path)).slice(0, limit);
}

// The wiki page that tells agents how to work in a task area: `type: guide`, `area: <AREA>`.
export function guideFor(vault, area) {
  return vault.pages.find(p => p.folder === 'wiki' && p.data.type === 'guide' && key(p.data.area ?? '') === key(area)) || null;
}

// Finds the record an agent tool keeps of the session working in a project.
// Claude Code, Codex and Copilot CLI each write every session to disk in their own layout; this
// lists a project's sessions as { tool, id, modified, current, source } and picks one. What a
// record means is left to the readers in stats.js and doctor.js.

export const SESSION_TOOLS = ['claude', 'codex', 'copilot'];

// Codex keeps every project's sessions in one tree; only the most recent files are opened.
const CODEX_FILES_SCANNED = 100;

// A record still being written can end in half a line; lines that do not parse are skipped.
export function jsonLines(path) {
  const records = [];
  for (const line of readFileSync(path, 'utf8').split('\n')) {
    if (!line) continue;
    try {
      records.push(JSON.parse(line));
    } catch {}
  }
  return records;
}

export function jsonFile(path) {
  try {
    return JSON.parse(readFileSync(path, 'utf8'));
  } catch {
    return {};
  }
}

const modifiedAt = path => statSync(path).mtimeMs;

// The project root as typed and as resolved: tools record the working directory either way.
function rootForms(root) {
  const forms = new Set([root]);
  try {
    forms.add(realpathSync(root));
  } catch {}
  return [...forms];
}

const isWithin = (roots, dir) => Boolean(dir) && roots.some(root => dir === root || dir.startsWith(root + sep));

// ---------- Claude Code ----------
// ~/.claude/projects/<working directory, non-alphanumerics as dashes>/<session>.jsonl, and next to
// it <session>/subagents/agent-<id>.jsonl with a .meta.json naming the agent type.
// source: { path, subagentDir }

const claudeHome = () => process.env.CLAUDE_CONFIG_DIR || join(homedir(), '.claude');

function claudeSessions(root) {
  const sessions = [];
  for (const form of rootForms(root)) {
    const dir = join(claudeHome(), 'projects', form.replace(/[^A-Za-z0-9]/g, '-'));
    if (!existsSync(dir)) continue;
    for (const name of readdirSync(dir)) {
      if (!name.endsWith('.jsonl')) continue;
      const id = name.slice(0, -'.jsonl'.length);
      const path = join(dir, name);
      sessions.push({
        tool: 'claude',
        id,
        modified: modifiedAt(path),
        current: id === process.env.CLAUDE_CODE_SESSION_ID,
        source: { path, subagentDir: join(dir, id, 'subagents') },
      });
    }
  }
  return sessions;
}

// ---------- Codex ----------
// ~/.codex/sessions/<year>/<month>/<day>/rollout-*.jsonl. The first line is the session's meta:
// its working directory and, for a subagent, the session that spawned it and its role.
// source: { files: [{ meta, records }] }, one file per agent

const codexHome = () => process.env.CODEX_HOME || join(homedir(), '.codex');

function rolloutFiles(dir, found = []) {
  if (!existsSync(dir)) return found;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) rolloutFiles(path, found);
    else if (entry.name.endsWith('.jsonl')) found.push({ path, modified: modifiedAt(path) });
  }
  return found;
}

function codexSessions(root) {
  const roots = rootForms(root);
  const recent = rolloutFiles(join(codexHome(), 'sessions')).sort((a, b) => b.modified - a.modified).slice(0, CODEX_FILES_SCANNED);
  const byId = new Map();
  for (const { path, modified } of recent) {
    const records = jsonLines(path);
    const meta = records[0]?.type === 'session_meta' ? records[0].payload : null;
    if (!meta || !isWithin(roots, meta.cwd)) continue;
    const id = meta.session_id || meta.id;
    if (!byId.has(id)) byId.set(id, { modified: 0, files: [] });
    const group = byId.get(id);
    group.modified = Math.max(group.modified, modified);
    group.files.push({ meta, records });
  }
  return [...byId].map(([id, { modified, files }]) => ({ tool: 'codex', id, modified, current: false, source: { files } }));
}

// ---------- Copilot CLI ----------
// ~/.copilot/session-state/<session>/events.jsonl, with the working directory in workspace.yaml.
// source: { path }

const copilotHome = () => join(homedir(), '.copilot');

function copilotSessions(root) {
  const roots = rootForms(root);
  const base = join(copilotHome(), 'session-state');
  if (!existsSync(base)) return [];
  const sessions = [];
  for (const id of readdirSync(base)) {
    const path = join(base, id, 'events.jsonl');
    const workspace = join(base, id, 'workspace.yaml');
    if (!existsSync(path) || !existsSync(workspace)) continue;
    const cwd = (readFileSync(workspace, 'utf8').match(/^cwd: (.*)$/m) || [])[1];
    if (!isWithin(roots, cwd)) continue;
    sessions.push({ tool: 'copilot', id, modified: modifiedAt(path), current: false, source: { path } });
  }
  return sessions;
}

// ---------- Choosing ----------

const LISTERS = { claude: claudeSessions, codex: codexSessions, copilot: copilotSessions };

// The session to report: the one named by `id` (a prefix is enough), else the session this command
// runs in when the tool says which one that is, else the most recently written one.
export function findSession(root, { tool, id } = {}) {
  let sessions = (tool ? [tool] : SESSION_TOOLS).flatMap(name => LISTERS[name](root));
  if (id) sessions = sessions.filter(session => session.id.startsWith(id));
  sessions.sort((a, b) => b.modified - a.modified);
  return (!id && sessions.find(session => session.current)) || sessions[0] || null;
}

// Session statistics: what an agent session has cost so far, as one row per agent: the main
// session and each subagent it started. Reads the session record found by sessions.js.

const MAIN = 'main';

// ---------- The summary being built ----------

const newStats = session => ({ tool: session.tool, id: session.id, agents: [], tools: {}, note: '' });

// Token fields stay null when the record does not hold them, so "unknown" never prints as 0.
const newAgent = name => ({
  name, model: '', steps: 0, first: null, peak: null, sent: null, cached: null, output: null, toolCalls: 0, start: null, end: null,
});

const plus = (sum, n) => (sum ?? 0) + (n || 0);

// One model request. `context` is everything sent with it, `cached` the part read from the cache.
function addStep(agent, { context, cached, output }) {
  agent.steps++;
  agent.first ??= context;
  agent.peak = Math.max(agent.peak ?? 0, context);
  agent.sent = plus(agent.sent, context);
  agent.cached = plus(agent.cached, cached);
  agent.output = plus(agent.output, output);
}

function addToolCall(stats, agent, name) {
  agent.toolCalls++;
  stats.tools[name] = (stats.tools[name] || 0) + 1;
}

// Widens the agent's working period to include this record.
function touch(agent, timestamp) {
  const time = Date.parse(timestamp);
  if (Number.isNaN(time)) return;
  agent.start = Math.min(agent.start ?? time, time);
  agent.end = Math.max(agent.end ?? time, time);
}

// Subagents are listed in the order they were started.
const byStart = (a, b) => (a.start ?? 0) - (b.start ?? 0);

// ---------- Claude Code ----------

function claudeAgent(stats, name, path) {
  const agent = newAgent(name);
  // A reply is written as one line per content block. Each line repeats the reply's usage, and
  // only the last one has the final output count, so the last line of a reply is the one kept.
  const replies = new Map();
  for (const record of jsonLines(path)) {
    touch(agent, record.timestamp);
    const message = record.type === 'assistant' && record.message;
    if (!message) continue;
    for (const block of message.content || []) {
      if (block.type === 'tool_use') addToolCall(stats, agent, block.name);
    }
    if (message.usage) replies.set(message.id, message);
  }
  for (const { model, usage } of replies.values()) {
    agent.model = model || agent.model;
    const cached = usage.cache_read_input_tokens || 0;
    addStep(agent, {
      context: (usage.input_tokens || 0) + cached + (usage.cache_creation_input_tokens || 0),
      cached,
      output: usage.output_tokens,
    });
  }
  return agent;
}

function claudeStats(session) {
  const { path, subagentDir } = session.source;
  const stats = newStats(session);
  stats.agents.push(claudeAgent(stats, MAIN, path));
  if (!existsSync(subagentDir)) return stats;
  const subagents = readdirSync(subagentDir)
    .filter(name => name.endsWith('.jsonl'))
    .map(name => {
      const meta = jsonFile(join(subagentDir, name.replace(/\.jsonl$/, '.meta.json')));
      return claudeAgent(stats, meta.agentType || 'subagent', join(subagentDir, name));
    });
  stats.agents.push(...subagents.sort(byStart));
  return stats;
}

// ---------- Codex ----------

function codexAgent(stats, name, records) {
  const agent = newAgent(name);
  let lastTotal = null;
  for (const record of records) {
    touch(agent, record.timestamp);
    const payload = record.payload || {};
    if (record.type === 'turn_context') agent.model = payload.model || agent.model;
    if (record.type === 'response_item' && /_call$/.test(payload.type || '')) addToolCall(stats, agent, payload.name || payload.type);
    if (record.type !== 'event_msg' || payload.type !== 'token_count' || !payload.info) continue;
    // The count is also repeated when only the rate limits change; a new request moves the total.
    const total = payload.info.total_token_usage?.total_tokens;
    if (total === lastTotal) continue;
    lastTotal = total;
    const last = payload.info.last_token_usage || {};
    addStep(agent, { context: last.input_tokens || 0, cached: last.cached_input_tokens, output: last.output_tokens });
  }
  return agent;
}

function codexStats(session) {
  const stats = newStats(session);
  const subagents = [];
  for (const { meta, records } of session.source.files) {
    if (meta.thread_source === 'subagent') subagents.push(codexAgent(stats, meta.agent_role || meta.agent_nickname || 'subagent', records));
    else stats.agents.push(codexAgent(stats, MAIN, records));
  }
  stats.agents.push(...subagents.sort(byStart));
  return stats;
}

// ---------- Copilot CLI ----------
// Events of a subagent carry its agentId. Token counts are written only when the session closes.

function copilotStats(session) {
  const stats = newStats(session);
  const agents = new Map();
  const agentOf = key => {
    if (!agents.has(key)) agents.set(key, newAgent(key));
    return agents.get(key);
  };
  agentOf(MAIN);
  let closed = false;
  for (const event of jsonLines(session.source.path)) {
    const data = event.data || {};
    const agent = agentOf(event.agentId || MAIN);
    touch(agent, event.timestamp);
    if (event.type === 'subagent.started') {
      agent.name = data.agentName || agent.name;
    } else if (event.type === 'assistant.message') {
      agent.steps++;
      agent.model = data.model || agent.model;
    } else if (event.type === 'tool.execution_start') {
      addToolCall(stats, agent, data.toolName);
    } else if (event.type === 'session.shutdown' && data.agentMetrics) {
      // A resumed session closes more than once; each close reports the run that ended with it.
      closed = true;
      for (const [key, metrics] of Object.entries(data.agentMetrics)) {
        const reported = agentOf(key);
        for (const { usage = {} } of Object.values(metrics.modelMetrics || {})) {
          reported.sent = plus(reported.sent, usage.inputTokens);
          reported.cached = plus(reported.cached, usage.cacheReadTokens);
          reported.output = plus(reported.output, usage.outputTokens);
        }
      }
    }
  }
  stats.agents = [...agents.values()];
  if (!closed) stats.note = 'Copilot writes token counts when the session closes; until then /usage shows them.';
  return stats;
}

const STATS_READERS = { claude: claudeStats, codex: codexStats, copilot: copilotStats };

export const sessionStats = session => STATS_READERS[session.tool](session);

// ---------- Printing ----------

const COLUMNS = ['agent', 'model', 'steps', 'first', 'peak', 'sent', 'cached', 'output', 'tools', 'min'];
const TEXT_COLUMNS = 2; // agent and model align left; the numbers after them align right
const LEGEND = 'first, peak: tokens sent with one request. sent: that, summed over every step. cached: the share of sent read from the cache.';

export function tokenCount(n) {
  if (n == null) return '-';
  if (n < 1000) return String(n);
  if (n < 1e6) return `${Math.round(n / 1000)}k`;
  return `${(n / 1e6).toFixed(1)}M`;
}

const cachedShare = agent => (agent.sent ? `${Math.round((100 * (agent.cached || 0)) / agent.sent)}%` : '-');
const minutes = (start, end) => Math.round((end - start) / 60000);

function clock(time) {
  const d = new Date(time);
  const two = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${two(d.getMonth() + 1)}-${two(d.getDate())} ${two(d.getHours())}:${two(d.getMinutes())}`;
}

// "2026-10-05 10:27 to 11:04, 37 min"; the end repeats the date only when it is another day.
function period(start, end) {
  const [from, to] = [clock(start), clock(end)];
  const sameDay = from.slice(0, 10) === to.slice(0, 10);
  return `${from} to ${sameDay ? to.slice(11) : to}, ${minutes(start, end)} min`;
}

function sessionPeriod(agents) {
  const timed = agents.filter(agent => agent.start != null);
  if (!timed.length) return '';
  return period(Math.min(...timed.map(agent => agent.start)), Math.max(...timed.map(agent => agent.end)));
}

// The sum of the agents. It has no context of its own and no period, so those cells stay empty.
function totalOf(agents) {
  const total = newAgent('total');
  for (const agent of agents) {
    total.steps += agent.steps;
    total.toolCalls += agent.toolCalls;
    for (const field of ['sent', 'cached', 'output']) {
      if (agent[field] != null) total[field] = plus(total[field], agent[field]);
    }
  }
  return total;
}

const cells = agent => [
  agent.name, agent.model, String(agent.steps), tokenCount(agent.first), tokenCount(agent.peak), tokenCount(agent.sent), cachedShare(agent),
  tokenCount(agent.output), String(agent.toolCalls), agent.start == null ? '' : String(minutes(agent.start, agent.end)),
];

// Rows of text cells as aligned lines: the first `textColumns` align left, the rest right.
export function alignedRows(rows, textColumns) {
  const widths = rows[0].map((_, column) => Math.max(...rows.map(row => row[column].length)));
  const pad = (cell, column) => (column < textColumns ? cell.padEnd(widths[column]) : cell.padStart(widths[column]));
  return rows.map(row => row.map(pad).join('  ').trimEnd());
}

export function formatStats(stats) {
  const { agents } = stats;
  const rows = [COLUMNS, ...agents.map(cells)];
  if (agents.length > 1) rows.push(cells(totalOf(agents)));
  const calls = Object.entries(stats.tools).sort((a, b) => b[1] - a[1]).map(([name, count]) => `${name} ${count}`);
  return [
    ['session', stats.tool, stats.id, sessionPeriod(agents)].filter(Boolean).join('  '),
    ...alignedRows(rows, TEXT_COLUMNS),
    `tool calls  ${calls.join('  ') || 'none'}`,
    LEGEND,
    ...(stats.note ? [stats.note] : []),
  ].join('\n');
}

// Start context: what an agent session carries before it has read anything. Rule and memory
// files, the lists of skills, agents and tools, and what plugins and hooks add are sent again with
// every step of every agent, so this is the cheapest place to make a session lighter.
// Reads the session record found by sessions.js and reduces it to parts with a size and a source.

// The command that shows the same context in tokens, in each tool.
const CONTEXT_COMMANDS = { claude: '/context', codex: '/status', copilot: '/context' };
const SMALL_PART_CHARS = 512; // smaller parts are summed into "other"
const SOURCES_SHOWN = 6;
const UNGROUPED = '(none)';
const NOT_STARTED = 'This session has not made a request yet; its context is recorded with the first one.';

// ---------- The report being built ----------

const newReport = session => ({ tool: session.tool, id: session.id, firstRequest: null, parts: [], note: '' });

// A part's sources are either texts with a size or groups with a count: { label, amount }.
// `chars` is null for a part the record counts in tokens instead.
const newPart = (name, measure) => ({ name, chars: 0, tokens: null, count: null, measure, sources: [] });

// A part made of texts, each from a named source.
function sized(name, texts) {
  const part = newPart(name, 'size');
  for (const [label, text] of texts) {
    part.chars += text.length;
    part.sources.push({ label, amount: text.length });
  }
  return part;
}

// A part that is one list of names, grouped by where each name comes from.
function listed(name, names, text, groupOf) {
  const part = newPart(name, 'count');
  part.chars = text.length;
  part.count = names.length;
  const groups = new Map();
  for (const item of names) groups.set(groupOf(item), (groups.get(groupOf(item)) || 0) + 1);
  part.sources = [...groups].map(([label, amount]) => ({ label, amount }));
  return part;
}

// "plugin:skill" and "plugin:agent" belong to the plugin; "mcp__server__tool" to the server.
const pluginOf = name => (name.includes(':') ? name.slice(0, name.indexOf(':')) : UNGROUPED);
const serverOf = name => (name.match(/^mcp__(.+?)__/) || [])[1] || UNGROUPED;

// "memory/MEMORY.md": the last folder says which of several same-named files this is.
const shortPath = path => `${basename(dirname(path))}/${basename(path)}`;

// ---------- Claude Code ----------
// Before the first reply the record holds one "attachment" per block of context the session was
// given: the instruction files, the skill, agent and tool lists, server instructions, hook output.

function claudePart(attachment) {
  switch (attachment.type) {
    case 'instructions':
      return sized('rule and memory files', (attachment.files || []).map(file => [shortPath(file.path), file.content || '']));
    case 'skill_listing':
      return listed('skill list', attachment.names || [], attachment.content || '', pluginOf);
    case 'agent_listing_delta':
      return listed('agent list', attachment.addedTypes || [], (attachment.addedLines || []).join('\n'), pluginOf);
    case 'deferred_tools_delta':
      return listed('tool names (loaded on demand)', attachment.addedNames || [], (attachment.addedLines || []).join('\n'), serverOf);
    case 'mcp_instructions_delta':
      return sized('MCP server instructions', (attachment.addedNames || []).map((name, i) => [name, attachment.addedBlocks?.[i] || '']));
    case 'hook_additional_context':
      return sized('session-start hooks', [[attachment.hookName || 'hook', [attachment.content].flat().join('\n')]]);
    default:
      return null;
  }
}

function claudeStart(session) {
  const report = newReport(session);
  for (const record of jsonLines(session.source.path)) {
    if (record.type === 'attachment') {
      const part = claudePart(record.attachment || {});
      if (part) report.parts.push(part);
    }
    const usage = record.type === 'assistant' && record.message?.usage;
    if (!usage) continue;
    report.firstRequest = (usage.input_tokens || 0) + (usage.cache_read_input_tokens || 0) + (usage.cache_creation_input_tokens || 0);
    break;
  }
  if (report.firstRequest == null) report.note = NOT_STARTED;
  return report;
}

// ---------- Codex ----------
// The session meta holds the base instructions. The messages before the first request hold the
// rest, one tagged block each: <skills_instructions>, <plugins_instructions>, the AGENTS.md text.

function codexBlockName(text) {
  if (text.startsWith('# AGENTS.md')) return 'AGENTS.md';
  const tag = (text.match(/^<([a-z_ ]+)>/) || [])[1];
  return tag ? tag.replace(/_/g, ' ') : null; // untagged text is the user's own request
}

function codexStart(session) {
  const report = newReport(session);
  const main = session.source.files.find(file => file.meta.thread_source !== 'subagent') || session.source.files[0];
  report.parts.push(sized('base instructions', [['codex', main.meta.base_instructions?.text || '']]));
  for (const record of main.records) {
    const payload = record.payload || {};
    if (record.type === 'response_item' && payload.type === 'message') {
      for (const block of payload.content || []) {
        const name = codexBlockName(block.text || '');
        if (name) report.parts.push(sized(name, [[payload.role, block.text]]));
      }
    }
    if (record.type !== 'event_msg' || payload.type !== 'token_count' || !payload.info) continue;
    report.firstRequest = payload.info.last_token_usage?.input_tokens ?? null;
    break;
  }
  if (report.firstRequest == null) report.note = NOT_STARTED;
  return report;
}

// ---------- Copilot CLI ----------
// The first system message holds the context as tagged blocks (<tools>, <custom_instruction>).
// A usage checkpoint, written later in the session, counts the tool definitions in tokens.

function copilotStart(session) {
  const report = newReport(session);
  const events = jsonLines(session.source.path);
  const system = events.find(event => event.type === 'system.message')?.data?.content || '';
  for (const [, tag, body] of system.matchAll(/<([a-z_]+)>(.*?)<\/\1>/gs)) report.parts.push(sized(tag.replace(/_/g, ' '), [['system', body]]));
  const checkpoint = events.find(event => event.type === 'session.usage_checkpoint')?.data?.promptCacheBreakState?.[0]?.models;
  const usage = checkpoint && Object.values(checkpoint)[0];
  if (usage?.tool_tokens == null) {
    report.note = 'Copilot counts its tool definitions at the first usage checkpoint; this session has not reached one.';
    return report;
  }
  report.parts.push({ ...newPart('tool definitions', 'count'), chars: null, tokens: usage.tool_tokens, count: usage.tool_count ?? null });
  return report;
}

const START_READERS = { claude: claudeStart, codex: codexStart, copilot: copilotStart };

// ---------- Tidying ----------

// Blocks with the same name become one part.
function mergedByName(parts) {
  const byName = new Map();
  for (const part of parts) {
    const known = byName.get(part.name);
    if (!known) {
      byName.set(part.name, part);
      continue;
    }
    known.chars += part.chars;
    known.sources.push(...part.sources);
  }
  return [...byName.values()];
}

// Largest first; parts too small to matter are summed into "other", which comes last.
function ranked(parts) {
  const other = newPart('other', 'size');
  const kept = [];
  for (const part of parts) {
    if (part.chars == null || part.chars >= SMALL_PART_CHARS) kept.push(part);
    else other.chars += part.chars;
  }
  kept.sort((a, b) => (b.chars ?? 0) - (a.chars ?? 0));
  return other.chars ? [...kept, other] : kept;
}

export function startContext(session) {
  const report = START_READERS[session.tool](session);
  report.parts = ranked(mergedByName(report.parts));
  for (const part of report.parts) part.sources.sort((a, b) => b.amount - a.amount);
  return report;
}

// ---------- Printing ----------

const kilobytes = chars => `${(chars / 1024).toFixed(chars < 10 * 1024 ? 1 : 0)} KB`;
const sizeOf = part => (part.chars == null ? `${tokenCount(part.tokens)} tokens` : kilobytes(part.chars));

// "213: marketing-skills 41, claude-seo 25, +9 more" for a list, "MEMORY.md 18 KB, AGENTS.md 11 KB"
// for texts. A part that is a single text says nothing its name and size have not said.
function sourcesOf(part) {
  if (part.measure === 'size' && part.sources.length < 2) return '';
  const amount = source => (part.measure === 'size' ? kilobytes(source.amount) : String(source.amount));
  const shown = part.sources.slice(0, SOURCES_SHOWN).map(source => `${source.label} ${amount(source)}`);
  const hidden = part.sources.length - shown.length;
  const list = shown.join(', ') + (hidden > 0 ? `, +${hidden} more` : '');
  return part.count == null ? list : [String(part.count), list].filter(Boolean).join(': ');
}

export function formatStartContext(report) {
  const rows = [['part', 'size', 'holds'], ...report.parts.map(part => [part.name, sizeOf(part), sourcesOf(part)])];
  const [nameWidth, sizeWidth] = [0, 1].map(column => Math.max(...rows.map(row => row[column].length)));
  return [
    `context at session start  ${report.tool}  ${report.id}`,
    ...(report.firstRequest == null ? [] : [`first request: ${tokenCount(report.firstRequest)} tokens`]),
    ...rows.map(([name, size, holds]) => `${name.padEnd(nameWidth)}  ${size.padStart(sizeWidth)}  ${holds}`.trimEnd()),
    `sizes are characters of text; ${CONTEXT_COMMANDS[report.tool]} shows this session's context in tokens`,
    ...(report.note ? [report.note] : []),
  ].join('\n');
}

// Superwiki CLI. Lives in a project at docs/.sw/sw.mjs and prints short answers,
// so agents do not have to read the vault to get them.

const SESSION_FLAGS = `[--session <id>] [--tool ${SESSION_TOOLS.join('|')}]`;

const HELP = `sw <command> [--docs <dir>] [--json]

  status          task counts per area and wiki page count
  ready           tasks that can start now, and tasks in progress
  check <ID>      can this task start / finish? lists what is open
  explain <ID>    a task's dependencies, what it blocks and unblocks, its plan and linked pages
  search <words>  pages and log entries that mention the words, best match first
  next-id <AREA>  next free task id for an area (numbers are never reused)
  lint            structural checks; exit code 1 on errors
  stats           what the agent session here has cost so far: steps, context and tokens per agent
  doctor          what that session carried before it read anything: rule files, skill and tool lists
                  both take ${SESSION_FLAGS} to look at another session of this project
  serve [--open]  start (or reuse) a local viewer at http://127.0.0.1:<port>/ that reads the files live
  snapshot        write docs/.sw/data.js so docs/viewer.html opens as a file, frozen at this moment`;

const SELF = fileURLToPath(import.meta.url);
const ROOT_FILES = ['index.md', 'log.md'];
const SERVER_IDLE_MS = 2 * 60 * 60 * 1000;
const LOG_HITS_SHOWN = 6;

// ---------- Reading the vault ----------

function walk(dir, rel, out) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith('.')) continue;
    const path = join(dir, entry.name);
    if (entry.isDirectory()) walk(path, `${rel}${entry.name}/`, out);
    else if (entry.name.endsWith('.md')) out.push({ path: rel + entry.name, text: readFileSync(path, 'utf8') });
  }
}

// The vault's markdown files as [{ path, text }]. The log only ever grows, so commands that do not
// show it record its presence without reading it.
function readFiles(docs, { withLog }) {
  const files = [];
  for (const name of ROOT_FILES) {
    if (!existsSync(join(docs, name))) continue;
    const skip = name === 'log.md' && !withLog;
    files.push({ path: name, text: skip ? '' : readFileSync(join(docs, name), 'utf8') });
  }
  for (const folder of VAULT_FOLDERS) {
    if (existsSync(join(docs, folder))) walk(join(docs, folder), `${folder}/`, files);
  }
  return files;
}

export function loadVault(docs) {
  return buildVault(readFiles(docs, { withLog: false }));
}

function readConfig(docs) {
  try {
    return JSON.parse(readFileSync(join(docs, '.sw', 'config.json'), 'utf8'));
  } catch {
    return {};
  }
}

// Everything the viewer shows, as one object.
export function vaultData(docs) {
  const config = readConfig(docs);
  return {
    name: config.name || basename(dirname(docs)),
    generated: new Date().toISOString(),
    config,
    files: readFiles(docs, { withLog: true }),
  };
}

// "<" is escaped so page text can never close the script element the viewer loads this with.
export const dataScript = data => `window.SW_DATA = ${JSON.stringify(data).replace(/</g, '\\u003c')};\n`;

// ---------- Vault commands ----------
// Each command gets { docs, vault, args, flags } and returns { data, text, code? } or
// { error, code? }. `data` is what --json prints; `text` is the default output.

function status({ vault }) {
  const s = summary(vault);
  const row = (name, c) =>
    `${name.padEnd(8)} total ${c.total}  ready ${c.ready}  in-progress ${c.progress}  blocked ${c.blocked}  done ${c.done}  cancelled ${c.cancelled}`;
  const rows = [...s.areas].map(([area, counts]) => row(area || '(none)', counts));
  if (s.areas.size > 1) rows.push(row('all', s.total));
  return {
    data: { areas: Object.fromEntries(s.areas), total: s.total, wikiPages: s.wikiPages },
    text: [...(rows.length ? rows : ['no tasks']), `wiki pages ${s.wikiPages}`].join('\n'),
  };
}

function ready({ vault }) {
  const inProgress = tasksIn(vault, 'progress');
  const startable = tasksIn(vault, 'ready');
  const brief = t => ({ id: t.id, title: t.title, milestone: t.milestone, priority: t.priority });
  const line = t => `${t.id}  ${t.title}${t.milestone ? `  [${t.milestone}]` : ''}${t.priority != null ? `  p${t.priority}` : ''}`;
  return {
    data: { inProgress: inProgress.map(brief), ready: startable.map(brief) },
    text: [`in progress (${inProgress.length})`, ...inProgress.map(line), `ready (${startable.length})`, ...startable.map(line)].join('\n'),
  };
}

function taskArg({ vault, args }) {
  const task = args[0] && taskOf(vault, args[0]);
  return task || { error: `no task ${args[0] ?? ''}` };
}

function check(ctx) {
  const t = taskArg(ctx);
  if (t.error) return { error: t.error };
  const openSoftDeps = t.openSoftDeps.filter(id => taskOf(ctx.vault, id));
  const canStart = t.status === 'todo' && !t.openDeps.length;
  const canFinish = !t.openDeps.length && !t.openSoftDeps.length;
  const plan = t.plan ? `docs/${t.plan.path}` : null;
  const openDeps = t.openDeps.length ? `  open deps: ${t.openDeps.join(', ')}` : '';
  const startLine = t.status === 'todo'
    ? `can start: ${canStart ? 'yes' : `no${openDeps}`}`
    : `can start: n/a, status is ${t.status}${openDeps}`;
  const draft = t.plan?.data.status === 'draft' ? '  (draft, not approved)' : '';
  return {
    data: { id: t.id, status: t.status, canStart, canFinish, openDeps: t.openDeps, openSoftDeps, plan, review: t.review || null },
    text: [
      `${t.id}  ${t.status}  ${t.title}`,
      startLine,
      `can finish: ${canFinish ? 'yes' : 'no'}${openSoftDeps.length ? `  open soft deps: ${openSoftDeps.join(', ')}` : ''}`,
      `plan: ${plan ? plan + draft : 'none'}`,
      `review: ${t.review ? `required (${t.review})` : 'not required'}`,
    ].join('\n'),
  };
}

function explain(ctx) {
  const { vault } = ctx;
  const t = taskArg(ctx);
  if (t.error) return { error: t.error };
  const describe = id => {
    const dep = taskOf(vault, id);
    return dep ? `${dep.id} (${dep.state}) ${dep.title}` : `${id} (unknown)`;
  };
  const section = (label, ids) => (ids.length ? [`${label}:`, ...ids.map(id => `  ${describe(id)}`)] : [`${label}: none`]);
  const linked = [...new Set(t.page.links.map(l => resolve(vault, l.target)).filter(p => p && p.folder === 'wiki'))];
  const unblocks = unblockedBy(vault, t.id);
  const guide = guideFor(vault, t.area);
  const plan = t.plan ? `docs/${t.plan.path}` : null;
  const guidePath = guide ? `docs/${guide.path}` : null;
  const facts = [
    `state: ${t.state} (status: ${t.status})`,
    t.milestone && `milestone: ${t.milestone}`,
    t.priority != null && `priority: ${t.priority}`,
    t.started && `started: ${t.started}`,
    t.finished && `finished: ${t.finished}`,
    t.review && `review: ${t.review}`,
  ].filter(Boolean);
  return {
    data: {
      id: t.id, title: t.title, status: t.status, state: t.state, milestone: t.milestone, priority: t.priority,
      started: t.started, finished: t.finished, deps: t.deps, softDeps: t.softDeps, dependents: t.dependents, unblocks,
      plan, guide: guidePath,
      linked: linked.map(p => ({ path: `docs/${p.path}`, type: p.data.type || '', summary: p.data.summary || '' })),
    },
    text: [
      `${t.id}  ${t.title}`,
      facts.join('  '),
      ...section('depends on', t.deps),
      ...(t.softDeps.length ? section('soft depends on', t.softDeps) : []),
      ...section('blocks', t.dependents),
      `finishing it makes ready: ${unblocks.join(', ') || 'nothing yet'}`,
      `task: docs/${t.page.path}`,
      `plan: ${plan ?? 'none'}`,
      `area guide: ${guidePath ?? 'none'}`,
      ...(linked.length
        ? ['linked pages:', ...linked.map(p => `  docs/${p.path}  [${p.data.type || '?'}]  ${p.data.summary || ''}`)]
        : ['linked pages: none']),
    ].join('\n'),
  };
}

// Log entries (heading plus first body line) that mention any of the terms. The log is not part of
// the loaded vault, so it is scanned here.
function searchLog(docs, terms) {
  const path = join(docs, 'log.md');
  if (!existsSync(path)) return [];
  const entries = [];
  let entry = null;
  for (const line of readFileSync(path, 'utf8').split(/\r?\n/)) {
    if (line.startsWith('## [')) {
      entry = { title: line.slice(3), text: '', hit: false };
      entries.push(entry);
    } else if (entry && line.trim() && !entry.text) {
      entry.text = line.trim().slice(0, 160);
    }
    if (entry && terms.some(term => line.toLowerCase().includes(term))) entry.hit = true;
  }
  return entries.filter(e => e.hit).map(e => `${e.title}${e.text ? `\n    ${e.text}` : ''}`);
}

function searchCommand({ docs, vault, args }) {
  const query = args.join(' ');
  if (!query.trim()) return { error: 'usage: sw search <words>' };
  const hits = search(vault, query);
  const logHits = searchLog(docs, query.toLowerCase().split(/\s+/).filter(w => w.length > 1));
  const shownLog = logHits.slice(-LOG_HITS_SHOWN);
  // Plans have no summary; their first heading says what they are.
  const about = p => p.data.summary || p.data.title || (p.body.match(/^#+\s+(.*)$/m) || [])[1] || '';
  const kind = p => (p.folder === 'tasks' ? `task ${taskOf(vault, p.data.id || p.name)?.state ?? ''}` : p.data.type || p.folder);
  return {
    data: {
      pages: hits.map(h => ({ path: `docs/${h.page.path}`, type: kind(h.page), summary: about(h.page), termsMatched: h.matched, line: h.line })),
      log: shownLog,
    },
    text: [
      `pages (${hits.length}), best match first; a page matching one common word is a weak match`,
      ...hits.map(h => `docs/${h.page.path}  [${kind(h.page)}]  ${about(h.page)}${h.line ? `\n    ${h.line}` : ''}`),
      `log entries (${logHits.length}${logHits.length > LOG_HITS_SHOWN ? `, last ${LOG_HITS_SHOWN} shown` : ''})`,
      ...shownLog,
    ].join('\n'),
  };
}

function nextIdCommand({ vault, args }) {
  const area = args[0];
  if (!area || !/^[A-Za-z][A-Za-z0-9]*$/.test(area)) return { error: 'usage: sw next-id <AREA>' };
  const id = nextId(vault, area);
  return { data: { id }, text: id };
}

function lintCommand({ vault }) {
  const findings = lint(vault);
  const errors = findings.filter(f => f.level === 'error').length;
  return {
    data: findings,
    text: [
      ...findings.map(f => `${f.level === 'error' ? 'E' : 'W'} ${f.code}  docs/${f.path}  ${f.message}`),
      `${errors} errors, ${findings.length - errors} warnings`,
    ].join('\n'),
    code: errors ? 1 : 0,
  };
}

function snapshot({ docs }) {
  const data = vaultData(docs);
  mkdirSync(join(docs, '.sw'), { recursive: true });
  writeFileSync(join(docs, '.sw', 'data.js'), dataScript(data));
  const text = `snapshot: ${data.files.length} files -> docs/.sw/data.js`;
  return { data: { files: data.files.length }, text };
}

// ---------- Session commands ----------
// These read the record an agent tool keeps of a session, not the vault. Tools file a session
// under the folder it ran in: the project root, which holds docs/.

function sessionArg(command, { docs, flags }) {
  if (flags.tool && !SESSION_TOOLS.includes(flags.tool)) return { error: `usage: sw ${command} ${SESSION_FLAGS}` };
  const root = dirname(docs);
  const session = findSession(root, { tool: flags.tool, id: flags.session });
  return session || { error: `no ${flags.tool || 'agent'} session record found for ${root}`, code: 1 };
}

function statsCommand(ctx) {
  const session = sessionArg('stats', ctx);
  if (session.error) return session;
  const stats = sessionStats(session);
  return { data: stats, text: formatStats(stats) };
}

function doctorCommand(ctx) {
  const session = sessionArg('doctor', ctx);
  if (session.error) return session;
  const report = startContext(session);
  return { data: report, text: formatStartContext(report) };
}

// ---------- Viewer server ----------
// A file:// page cannot read local files unless the user picks a folder. Served from localhost it
// can: every Refresh asks this process, which reads the files as they are now.

const serverStatePath = docs => join(docs, '.sw', 'server.json');

function readServerState(docs) {
  try {
    return JSON.parse(readFileSync(serverStatePath(docs), 'utf8'));
  } catch {
    return null;
  }
}

async function servesDocs(url, docs) {
  try {
    return (await (await fetch(`${url}.sw/ping`)).text()) === docs;
  } catch {
    return false;
  }
}

function runServer(docs) {
  let lastRequest = Date.now();
  const server = createServer((req, res) => {
    lastRequest = Date.now();
    const { port } = server.address();
    // Only this machine's browser, addressed by its loopback name, gets an answer.
    if (![`127.0.0.1:${port}`, `localhost:${port}`].includes(req.headers.host)) {
      res.writeHead(403).end();
      return;
    }
    const send = (type, body) => {
      res.writeHead(200, { 'content-type': `${type}; charset=utf-8`, 'cache-control': 'no-store' });
      res.end(body);
    };
    const path = (req.url || '/').split('?')[0];
    const viewer = join(docs, 'viewer.html');
    if (path === '/' || path === '/viewer.html') {
      if (existsSync(viewer)) send('text/html', readFileSync(viewer));
      else res.writeHead(404).end('docs/viewer.html is missing; run sw-init');
    } else if (path === '/.sw/data.js') {
      send('text/javascript', dataScript({ ...vaultData(docs), live: true }));
    } else if (path === '/.sw/ping') {
      send('text/plain', docs);
    } else {
      res.writeHead(404).end();
    }
  });
  server.listen(0, '127.0.0.1', () => {
    mkdirSync(join(docs, '.sw'), { recursive: true });
    writeFileSync(serverStatePath(docs), JSON.stringify({ url: `http://127.0.0.1:${server.address().port}/`, pid: process.pid }) + '\n');
  });
  setInterval(() => {
    if (Date.now() - lastRequest > SERVER_IDLE_MS) process.exit(0);
  }, 60 * 1000);
}

// The URL of this project's viewer server, starting a detached one if none is running.
async function ensureServer(docs) {
  const running = readServerState(docs)?.url;
  if (running && (await servesDocs(running, docs))) return running;
  spawn(process.execPath, [SELF, 'serve', '--foreground', '--docs', docs], { detached: true, stdio: 'ignore' }).unref();
  for (let attempt = 0; attempt < 50; attempt++) {
    await new Promise(done => setTimeout(done, 100));
    const url = readServerState(docs)?.url;
    if (url && (await servesDocs(url, docs))) return url;
  }
  return null;
}

function openInBrowser(url) {
  const [bin, args] = process.platform === 'darwin' ? ['open', [url]]
    : process.platform === 'win32' ? ['cmd', ['/c', 'start', '', url]]
    : ['xdg-open', [url]];
  spawn(bin, args, { detached: true, stdio: 'ignore' }).unref();
}

async function serve({ docs, flags }) {
  if (flags.foreground) {
    runServer(docs);
    return null; // keeps running; no result to print
  }
  const url = await ensureServer(docs);
  if (!url) return { error: 'could not start the viewer server; use `snapshot` and open docs/viewer.html instead', code: 1 };
  if (flags.open) openInBrowser(url);
  return { data: { url }, text: url };
}

// ---------- Entry point ----------

const COMMANDS = {
  status: { run: status, needsVault: true },
  ready: { run: ready, needsVault: true },
  check: { run: check, needsVault: true },
  explain: { run: explain, needsVault: true },
  search: { run: searchCommand, needsVault: true },
  'next-id': { run: nextIdCommand, needsVault: true },
  lint: { run: lintCommand, needsVault: true },
  stats: { run: statsCommand, needsVault: false },
  doctor: { run: doctorCommand, needsVault: false },
  snapshot: { run: snapshot, needsVault: false },
  serve: { run: serve, needsVault: false },
};

// Flags that are on or off, and flags that take the next argument as their value.
const SWITCHES = ['json', 'open', 'foreground'];
const OPTIONS = ['docs', 'tool', 'session'];

// Anything that is not a known flag is positional, so search words may start with dashes.
function parseArgs(argv) {
  const flags = Object.fromEntries([...SWITCHES.map(name => [name, false]), ...OPTIONS.map(name => [name, null])]);
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const name = argv[i].startsWith('--') ? argv[i].slice(2) : null;
    if (SWITCHES.includes(name)) flags[name] = true;
    else if (OPTIONS.includes(name)) flags[name] = argv[++i] ?? null;
    else positional.push(argv[i]);
  }
  return { command: positional[0], args: positional.slice(1), flags };
}

// --docs wins; otherwise the docs folder this script was installed into; otherwise ./docs.
function docsDir(flags) {
  if (flags.docs) return resolvePath(flags.docs);
  const installedIn = join(dirname(SELF), '..');
  return existsSync(join(installedIn, 'index.md')) ? installedIn : resolvePath('docs');
}

async function main(argv) {
  const { command, args, flags } = parseArgs(argv);
  if (!command || command === 'help' || command === '--help') {
    console.log(HELP);
    return 0;
  }
  const entry = COMMANDS[command];
  if (!entry) {
    console.error(`unknown command ${command}\n\n${HELP}`);
    return 2;
  }
  const docs = docsDir(flags);
  if (!existsSync(docs)) {
    console.error(`no docs folder at ${docs}; run sw-init or pass --docs`);
    return 2;
  }
  const result = await entry.run({ docs, args, flags, vault: entry.needsVault ? loadVault(docs) : null });
  if (result === null) return null;
  if (result.error) {
    console.error(result.error);
    return result.code ?? 2;
  }
  console.log(flags.json ? JSON.stringify(result.data, null, 2) : result.text);
  return result.code ?? 0;
}

// realpath: the script may be reached through a symlinked path (macOS /tmp, linked skills folders).
if (process.argv[1] && realpathSync(process.argv[1]) === realpathSync(SELF)) {
  const code = await main(process.argv.slice(2));
  if (code !== null) process.exitCode = code;
}
